// ============================================================================
// GEMINI CLIENT
// ============================================================================

function getGemini(): GoogleGenAI | null {
    try {
        const apiKey = process.env.GEMINI_API_KEY;
        if (!apiKey) return null;
        return new GoogleGenAI({ apiKey });
    } catch {
        return null;
    }
}

// Simple in-memory cache (TTL 30 min)
const aiCache = new Map<string, { data: any; ts: number }>();
const CACHE_TTL = 30 * 60 * 1000;

function getCached(key: string): any | null {
    const entry = aiCache.get(key);
    if (!entry) return null;
    if (Date.now() - entry.ts > CACHE_TTL) { aiCache.delete(key); return null; }
    return entry.data;
}

function setCache(key: string, data: any): void {
    aiCache.set(key, { data, ts: Date.now() });
    if (aiCache.size > 100) {
        const oldest = [...aiCache.entries()].sort((a, b) => a[1].ts - b[1].ts)[0];
        if (oldest) aiCache.delete(oldest[0]);
    }
}

